    char base[] = "abcdefghijklmnopqrstuvwxyz0123456789";
    srand(seed);
    char domain[16];
    for (int i=0; i<12; i++) domain[i] = base[rand() % 36];
    domain[12] = '.';
    domain[13] = 't';
    domain[14] = 'v';
